package com.bleachmod.common.appearance;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.*;

/**
 * Pieces the character editor may combine. Bundled in the mod jar and read from the classpath on
 * both sides, so client and server always agree (the protocol version pins the mod version).
 * Generated by tools/appearance/split_skin.py.
 */
public final class AppearanceCatalog {
    public static final String PATH = "/data/bleachmod/appearance/catalog.json";
    public static final List<String> CATEGORIES = List.of("base", "outfit", "hair", "eyes", "mouth");
    /** Categories the player may leave empty. */
    public static final Set<String> OPTIONAL = Set.of("outfit", "hair", "eyes", "mouth");
    public static final Set<String> TINTS = Set.of("none", "skin", "hair", "eye");

    public record Layer(String texture, String tint) { }
    public record Piece(String id, String category, String inspiredBy, List<String> races, String unlock,
                        List<Layer> layers, int defaultColor) {
        public boolean allows(String race) { return races.isEmpty() || races.contains(race); }
        public boolean free() { return unlock == null || unlock.isEmpty(); }
    }
    public record RaceDefaults(Map<String, String> pieces, int skinColor) { }

    private static AppearanceCatalog instance;
    private final Map<String, Piece> pieces = new LinkedHashMap<>();
    private final Map<String, RaceDefaults> defaults = new HashMap<>();
    private final Map<String, List<Integer>> palettes = new HashMap<>();

    public static synchronized AppearanceCatalog get() {
        if (instance == null) {
            try (InputStream in = AppearanceCatalog.class.getResourceAsStream(PATH)) {
                if (in == null) throw new IllegalStateException("Missing " + PATH);
                instance = parse(JsonParser.parseReader(new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject());
            } catch (java.io.IOException e) {
                throw new IllegalStateException("Unreadable " + PATH, e);
            }
        }
        return instance;
    }

    public static AppearanceCatalog parse(JsonObject json) {
        AppearanceCatalog catalog = new AppearanceCatalog();
        for (JsonElement element : json.getAsJsonArray("pieces")) {
            JsonObject o = element.getAsJsonObject();
            String id = o.get("id").getAsString(), category = o.get("category").getAsString();
            if (!CATEGORIES.contains(category) || !id.startsWith(category + ":"))
                throw new IllegalArgumentException("Bad appearance piece " + id);
            List<Layer> layers = new ArrayList<>();
            for (JsonElement l : o.getAsJsonArray("layers")) {
                String tint = l.getAsJsonObject().get("tint").getAsString();
                if (!TINTS.contains(tint)) throw new IllegalArgumentException(id + ": unknown tint " + tint);
                layers.add(new Layer(l.getAsJsonObject().get("texture").getAsString(), tint));
            }
            catalog.pieces.put(id, new Piece(id, category, o.has("inspiredBy") ? o.get("inspiredBy").getAsString() : "",
                    strings(o.getAsJsonArray("races")), o.has("unlock") && !o.get("unlock").isJsonNull() ? o.get("unlock").getAsString() : null,
                    List.copyOf(layers), o.has("defaultColor") ? color(o.get("defaultColor").getAsString()) : 0xFFFFFF));
        }
        for (String palette : List.of("skinColors", "hairColors", "eyeColors")) {
            List<Integer> colors = new ArrayList<>();
            if (json.has(palette)) for (JsonElement c : json.getAsJsonArray(palette)) colors.add(color(c.getAsString()));
            catalog.palettes.put(palette, List.copyOf(colors));
        }
        for (Map.Entry<String, JsonElement> race : json.getAsJsonObject("defaults").entrySet()) {
            JsonObject o = race.getValue().getAsJsonObject();
            Map<String, String> chosen = new HashMap<>();
            for (String category : CATEGORIES) {
                String id = o.has(category) ? o.get(category).getAsString() : "";
                if (!id.isEmpty() && !catalog.valid(id, category, race.getKey()))
                    throw new IllegalArgumentException("Default " + id + " is not a valid " + category + " for " + race.getKey());
                chosen.put(category, id);
            }
            if (chosen.get("base").isEmpty()) throw new IllegalArgumentException(race.getKey() + ": missing default base");
            catalog.defaults.put(race.getKey(), new RaceDefaults(Map.copyOf(chosen), color(o.get("skinColor").getAsString())));
        }
        return catalog;
    }

    private static List<String> strings(JsonArray array) {
        List<String> out = new ArrayList<>();
        if (array != null) array.forEach(e -> out.add(e.getAsString()));
        return List.copyOf(out);
    }

    /** "#RRGGBB" to 0xRRGGBB; anything else is rejected. */
    public static int color(String hex) {
        if (hex == null || !hex.matches("#[0-9A-Fa-f]{6}")) throw new IllegalArgumentException("Bad color " + hex);
        return Integer.parseInt(hex.substring(1), 16);
    }

    public Optional<Piece> piece(String id) { return Optional.ofNullable(pieces.get(id)); }

    /** True when the id names a free piece of that category that the race may wear. */
    public boolean valid(String id, String category, String race) {
        Piece p = pieces.get(id);
        return p != null && p.category().equals(category) && p.allows(race) && p.free();
    }

    public List<Piece> pieces(String category, String race) {
        return pieces.values().stream().filter(p -> p.category().equals(category) && p.allows(race) && p.free()).toList();
    }

    public List<String> ids(String category) {
        return pieces.values().stream().filter(p -> p.category().equals(category)).map(Piece::id).toList();
    }

    public RaceDefaults defaults(String race) {
        RaceDefaults d = defaults.get(race);
        return d != null ? d : defaults.values().iterator().next();
    }

    public List<Integer> palette(String name) { return palettes.getOrDefault(name, List.of()); }
}
